cat > scripts/write.py <<'EOF'
import json,subprocess,sys
OUT="/Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/web/public/images/cars"
TS="/Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/web/src/lib/car-images.ts"
picks=json.load(open("dl/picks.json"))
alts={"f70-front":"Grey BMW 1 Series (F70, 120) hatchback, front three-quarter view",
"f70-rear":"White BMW 1 Series (F70, 118d M Sport) hatchback, rear three-quarter view",
"g60-front":"Grey BMW i5 eDrive40 M Sport (5 Series G60) sedan, front three-quarter view",
"g60-interior":"BMW 5 Series (G60) cockpit with curved display and steering wheel",
"g70-front":"Oxide Grey BMW i7 xDrive60 (7 Series G70) sedan in a showroom, front three-quarter view",
"g70-rear":"Grey BMW i7 xDrive60 (7 Series G70) sedan at BMW Welt, rear three-quarter view"}
ent={}
for p in picks:
    if p["author"]=="© M 93": p["author"]="M 93"
    f=p["file"]+".webp"
    wh=subprocess.run(["sips","-g","pixelWidth","-g","pixelHeight",f"{OUT}/{f}"],capture_output=True,text=True).stdout.split()
    w,h=int(wh[wh.index("pixelWidth:")+1]),int(wh[wh.index("pixelHeight:")+1])
    side={"source":"Wikimedia Commons","page":p["page"],"author":p["author"],"licence":p["licence"],"licenceUrl":p["licenceUrl"],"title":p["title"],"model":p["model"],"view":p["view"],"modified":"resized to 1600 px, converted to WebP"}
    json.dump(side,open(f"{OUT}/{f}.json","w"),indent=2,ensure_ascii=False)
    slot="front" if p["view"]=="front" else "second"
    ent.setdefault(p["model"],{})[slot]=dict(src=f"/images/cars/{f}",alt=alts[p["file"]],width=w,height=h,credit=f'Photo: {p["author"]}, {p["licence"]}, via Wikimedia Commons',licence=p["licence"],page=p["page"])
lines=["""// Real photos of the three current BMW model generations, from Wikimedia Commons.
// All are CC BY-SA (3.0 DE / 4.0): reuse requires visible attribution (author +
// licence + link) and a note that they were modified (resized, WebP). Render
// `credit` next to each image and link it to `page`. Per-file details live in the
// JSON sidecars in web/public/images/cars/.

export interface CarImage {
  src: string;
  alt: string;
  width: number;
  height: number;
  credit: string;
  licence: string;
  page: string;
}

export const CAR_IMAGES: Record<"F70" | "G60" | "G70", { front: CarImage; second: CarImage }> = {"""]
for m in ["F70","G60","G70"]:
    lines.append(f"  {m}: {{")
    for slot in ["front","second"]:
        e=ent[m][slot]
        lines.append(f"    {slot}: {{")
        for k in ["src","alt","width","height","credit","licence","page"]:
            lines.append(f"      {k}: {json.dumps(e[k],ensure_ascii=False)},")
        lines.append("    },")
    lines.append("  },")
lines.append("};\n")
open(TS,"w").write("\n".join(lines))
EOF
python3 -I scripts/write.py && cat /Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/web/src/lib/car-images.ts && cat /Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/web/public/images/cars/f70-rear.webp.json
cd /Volumes/PJ/peresjav/hackathons/ehl-final-minuch-2026/web && npx tsc --noEmit -p . 2>&1 | grep car-images

